CREATE OR REPLACE FUNCTION public.fn_adjust_inventory_count(p_business_id uuid, p_inventory_item_id uuid, p_location_id uuid, p_new_qty numeric, p_reason text, p_notes text)
 RETURNS inventory_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stock inventory_stock;
BEGIN

 IF p_new_qty IS NOT NULL AND p_new_qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'p_new_qty must be finite'; END IF;
  if p_business_id is distinct from current_business_id() then
    raise exception 'business_id mismatch';
  end if;

  if not user_can('adjustInventory') then
    raise exception 'permission denied: adjustInventory required';
  end if;

  if not exists (
    select 1 from inventory_items
    where id = p_inventory_item_id
      and business_id = p_business_id
  ) then
    raise exception 'inventory item not found';
  end if;

  if not exists (
    select 1 from locations
    where id = p_location_id
      and business_id = p_business_id
  ) then
    raise exception 'location not found';
  end if;

  if p_new_qty is null or p_new_qty < 0 then
    raise exception 'counted quantity cannot be negative';
  end if;

  insert into inventory_stock (inventory_item_id, location_id, qty, avg_cost_per_unit)
  values (p_inventory_item_id, p_location_id, 0, 0)
  on conflict (inventory_item_id, location_id) do nothing;

  select * into v_stock
  from inventory_stock
  where inventory_item_id = p_inventory_item_id
    and location_id = p_location_id for update;

  return fn_record_inventory_movement(
    p_business_id,
    p_inventory_item_id,
    p_location_id,
    'ADJUSTMENT',
    p_new_qty - v_stock.qty,
    v_stock.avg_cost_per_unit,
    null,
    null,
    null,
    'Reason: ' || p_reason ||
      coalesce(' — ' || nullif(p_notes, ''), ''),
    true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_transfer_inventory(p_business_id uuid, p_inventory_item_id uuid, p_from_location_id uuid, p_to_location_id uuid, p_qty numeric, p_notes text)
 RETURNS inventory_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_from_stock public.inventory_stock; v_out_tx public.inventory_transactions;
BEGIN

 IF p_qty IS NOT NULL AND p_qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'p_qty must be finite'; END IF;
 IF p_business_id IS DISTINCT FROM public.current_business_id() THEN RAISE EXCEPTION 'business_id mismatch'; END IF;
 IF NOT coalesce(public.user_can('adjustInventory'),false) THEN RAISE EXCEPTION 'permission denied: adjustInventory required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.inventory_items WHERE id=p_inventory_item_id AND business_id=p_business_id) THEN RAISE EXCEPTION 'inventory item not found'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.locations WHERE id=p_from_location_id AND business_id=p_business_id) THEN RAISE EXCEPTION 'source location not found'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.locations WHERE id=p_to_location_id AND business_id=p_business_id) THEN RAISE EXCEPTION 'destination location not found'; END IF;
 IF p_qty IS NULL OR p_qty <= 0 OR p_qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'transfer quantity must be greater than zero'; END IF;
 IF p_from_location_id=p_to_location_id THEN RAISE EXCEPTION 'source and destination locations must differ'; END IF;
 -- Both directions create and lock the same rows in UUID order before taking a source snapshot.
 INSERT INTO public.inventory_stock(inventory_item_id,location_id,qty,avg_cost_per_unit)
 SELECT p_inventory_item_id,l.id,0,0 FROM public.locations l
 WHERE l.id IN(p_from_location_id,p_to_location_id) ORDER BY l.id
 ON CONFLICT(inventory_item_id,location_id) DO NOTHING;
 PERFORM s.id FROM public.inventory_stock s
 WHERE s.inventory_item_id=p_inventory_item_id AND s.location_id IN(p_from_location_id,p_to_location_id)
 ORDER BY s.location_id FOR UPDATE;
 SELECT * INTO v_from_stock FROM public.inventory_stock WHERE inventory_item_id=p_inventory_item_id AND location_id=p_from_location_id;
 IF v_from_stock.qty < p_qty THEN RAISE EXCEPTION 'only % in stock at source location — cannot transfer more than that',v_from_stock.qty; END IF;
 v_out_tx := public.fn_record_inventory_movement(p_business_id,p_inventory_item_id,p_from_location_id,'TRANSFER_OUT',-p_qty,v_from_stock.avg_cost_per_unit,NULL,NULL,NULL,COALESCE(p_notes,'Transfer to another location'),FALSE);
 PERFORM public.fn_record_inventory_movement(p_business_id,p_inventory_item_id,p_to_location_id,'TRANSFER_IN',p_qty,v_from_stock.avg_cost_per_unit,NULL,NULL,v_out_tx.id,COALESCE(p_notes,'Transfer from another location'),TRUE);
 RETURN v_out_tx;
END; $function$

CREATE OR REPLACE FUNCTION public.fn_record_inventory_movement(p_business_id uuid, p_inventory_item_id uuid, p_location_id uuid, p_type text, p_qty_change numeric, p_unit_cost numeric, p_sale_id uuid, p_purchase_order_id uuid, p_related_transaction_id uuid, p_note text, p_allow_negative boolean)
 RETURNS inventory_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stock inventory_stock;
  v_new_qty numeric;
  v_new_avg numeric;
  v_prev_avg numeric;
  v_tx inventory_transactions;
BEGIN

 IF p_qty_change IS NOT NULL AND p_qty_change::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'p_qty_change must be finite'; END IF;
 IF p_unit_cost IS NOT NULL AND p_unit_cost::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'p_unit_cost must be finite'; END IF;
  if p_business_id is distinct from current_business_id() then
    raise exception 'business_id mismatch';
  end if;

  if not exists (
    select 1 from inventory_items
    where id = p_inventory_item_id and business_id = p_business_id
  ) then
    raise exception 'inventory item not found';
  end if;

  if not exists (
    select 1 from locations
    where id = p_location_id and business_id = p_business_id
  ) then
    raise exception 'location not found';
  end if;

  select * into v_stock
  from inventory_stock
  where inventory_item_id = p_inventory_item_id
    and location_id = p_location_id
  for update;

  if v_stock.id is null then
    insert into inventory_stock (
      inventory_item_id, location_id, qty, avg_cost_per_unit
    )
    values (
      p_inventory_item_id, p_location_id, 0, 0
    )
    returning * into v_stock;
  end if;

  v_prev_avg := v_stock.avg_cost_per_unit;
  v_new_qty := round(v_stock.qty + p_qty_change, 3);

  if v_new_qty < 0 and not p_allow_negative then
    raise exception
      'insufficient stock: item % at location % would go to % (negative not allowed)',
      p_inventory_item_id, p_location_id, v_new_qty;
  end if;

  if p_type in ('PURCHASE','INITIAL_STOCK','TRANSFER_IN')
     and p_qty_change > 0
     and p_unit_cost is not null then

    if v_new_qty > 0 then
      v_new_avg := round(
        (
          (v_stock.qty * v_stock.avg_cost_per_unit)
          + (p_qty_change * p_unit_cost)
        ) / v_new_qty,
        4
      );
    else
      v_new_avg := p_unit_cost;
    end if;
  else
    v_new_avg := v_stock.avg_cost_per_unit;
  end if;

  update inventory_stock
  set
    qty = v_new_qty,
    avg_cost_per_unit = v_new_avg,
    last_purchase_cost = case
      when p_type in ('PURCHASE','INITIAL_STOCK') then p_unit_cost
      else last_purchase_cost
    end,
    last_purchase_date = case
      when p_type in ('PURCHASE','INITIAL_STOCK') then now()
      else last_purchase_date
    end,
    updated_at = now()
  where inventory_item_id = p_inventory_item_id
    and location_id = p_location_id;

  insert into inventory_transactions (
    business_id,
    inventory_item_id,
    location_id,
    type,
    qty_change,
    unit,
    unit_cost,
    total_cost,
    sale_id,
    purchase_order_id,
    related_transaction_id,
    prev_avg_cost,
    new_avg_cost,
    note,
    created_by
  )
  select
    p_business_id,
    p_inventory_item_id,
    p_location_id,
    p_type,
    p_qty_change,
    i.unit,
    coalesce(p_unit_cost, v_prev_avg),
    round(p_qty_change * coalesce(p_unit_cost, v_prev_avg), 2),
    p_sale_id,
    p_purchase_order_id,
    p_related_transaction_id,
    v_prev_avg,
    v_new_avg,
    p_note,
    auth.uid()
  from inventory_items i
  where i.id = p_inventory_item_id
  returning * into v_tx;

  return v_tx;
end;
$function$
